    static async Task<T> ReviewGet<T>(Server s,string path){using var response=await s.Browser.GetAsync(path);Assert.True(response.IsSuccessStatusCode,await response.Content.ReadAsStringAsync());return (await response.Content.ReadFromJsonAsync<T>(WireJson.Options))!;}
    static async Task<HttpResponseMessage> ReviewSend(Server s,string path,object value,HttpClient? browser=null)
    {
        browser??=s.Browser;var session=await browser.GetFromJsonAsync<JsonElement>("/api/session");using var request=new HttpRequestMessage(HttpMethod.Post,path){Content=JsonContent.Create(value,options:WireJson.Options)};request.Headers.Add("Origin",s.Origin);request.Headers.Add("X-AeroScience-Organization-CSRF",session.GetProperty("csrf").GetString());return await browser.SendAsync(request);
    }
    static string ReviewPath(Guid root)=>"/api/organization/reviews/"+root;
    static async Task<ResearchReviewCommandResult> ReviewCommand(SubmissionFixture f,SubmissionDraft row,ResearchReviewAction action,string note="",ReviewTarget? target=null,ReviewEvidenceReference[]? evidence=null,Guid[]? resolve=null)
    {
        var root=row.Manifest.ReviewLink?.RootReceiptId??row.Receipt!.Id;var current=await ReviewGet<ResearchReviewSnapshot>(f.Server,ReviewPath(root));return(await f.Server.Post(ReviewPath(root)+"/commands",new ResearchReviewCommand(1,Guid.NewGuid(),current.Summary.Revision,action,target,note,evidence,resolve,action==ResearchReviewAction.Approve))).Deserialize<ResearchReviewCommandResult>(WireJson.Options)!;
    }
    static async Task<PersonalResearchAttempt> AtmosphericRecording(SubmissionFixture f,PreparedOrganizationMission p,bool partial=false)
    {
        var start=DateTimeOffset.UtcNow;var time=start;using var research=new ResearchOperations(f.Store,f.Science);var coordinator=new MissionCoordinator(f.Store,1000,research:research,utcNow:()=>time);var plan=f.Store.SavePlan(p.Plan with{Instruments=[new("ambient-temperature",true)],StartScienceArmed=true});
        void Observe(int i){time=start.AddSeconds(i);var frame=SubmissionFixture.Frame(time) with{AltitudeMslFeet=1100+(partial?0:Math.Min(2,i/4))*500};coordinator.Apply(new(new(ConnectionState.Connected,frame.Source,"Explicit synthetic atmosphere",time),frame,new(time,17.1234567-Math.Min(2,i/4),29.9,5,270,.002)));}
        Observe(0);var flight=coordinator.Start(new("Synthetic atmospheric original readings",PlanId:plan.Id));var state=coordinator.ScienceCollection(flight.Id)!.State!;coordinator.ControlScience(new(1,flight.Id,Guid.NewGuid(),state.Revision,CollectionAction.StartData,null));for(int i=1;i<=12;i++)Observe(i);await Task.Delay(TimeSpan.FromSeconds(12));coordinator.End(flight.Id);return f.Store.EvaluateResearchAttempt(new(Guid.NewGuid(),flight.Id,start,time,CardId:p.Card.Id),science:f.Science);
    }
    [PostgresFact]public async Task AtmosphericReviewRequestsExplicitSupplementalConsentAndApprovalSurviveRestartWithoutChangingOriginals()
    {
        await using var f=await SubmissionFixture.Create();var c=await f.Card(AtmosphericResearch.Template,incomplete:true);var result=await AtmosphericRecording(f,c.Prepared);Assert.Equal(ResearchAttemptOutcome.CollectionComplete,result.Outcome);var all=f.Store.PreviewSubmission(new(1,Guid.NewGuid(),0,result.FlightId,[result.Id],null,"Original incomplete selection",f.Upload),f.Science);var initial=f.Draft(result,all.Manifest.Items.Where(i=>i.Kind!=SubmissionEvidenceKind.ScientificObservations).Select(i=>i.Key).ToArray());await f.ReviewApprove(initial);using var delivery=f.Delivery();var received=await delivery.Send(initial.Id,default);var root=received.Receipt!.Id;var originalHash=received.Consent!.PayloadSha256;var target=new ReviewTarget(c.Prepared.Card.Id,"collection");
        var queue=await ReviewGet<OrganizationPage<ResearchReviewSummary>>(f.Server,"/api/organization/reviews?state=awaitingReview&search=Synthetic");Assert.Empty(queue.Items);queue=await ReviewGet<OrganizationPage<ResearchReviewSummary>>(f.Server,"/api/organization/reviews");Assert.Single(queue.Items);Assert.Equal(root,queue.Items[0].RootReceiptId);
        var inspected=(await f.Server.Post(ReviewPath(root)+"/evidence",new ResearchReviewSelection(target.CardId,target.RequirementKey,[root]))).Deserialize<ResearchReviewEvidencePage>(WireJson.Options)!;Assert.False(inspected.Assessment.CanApprove);Assert.DoesNotContain(inspected.Items,i=>i.Item.Data.Observations is not null);
        var request=await ReviewCommand(f,received,ResearchReviewAction.RequestEvidence,"Please provide the retained original temperature observations for the sampled altitude bands.",target);var check=new LocalReviewCheck(f.Upload,root);var status=await f.Desktop.ReviewStatus(received.Id,check,f.Store,default);Assert.True(status.VerifiedNow);Assert.Equal(ResearchReviewState.MoreEvidenceRequested,status.Retained!.Snapshot.Summary.State);Assert.False((await f.Desktop.ReviewStatus(received.Id,new(f.Read,root),f.Store,default)).VerifiedNow);Assert.Equal(1,f.Server.SubmissionWrites);
        await Assert.ThrowsAsync<ArgumentException>(()=>f.Desktop.RespondToReview(received.Id,new(f.Upload,root,new(1,Guid.NewGuid(),request.Review.Summary.Revision,ResearchReviewAction.PilotResponse,target,"No consent",RespondTo:request.Event.Id)),f.Store,default));var response=await f.Desktop.RespondToReview(received.Id,new(f.Upload,root,new(1,Guid.NewGuid(),request.Review.Summary.Revision,ResearchReviewAction.PilotResponse,target,"The existing recorded observations are available; I will select them explicitly.",RespondTo:request.Event.Id,ExplicitSharing:true)),f.Store,default);Assert.Equal(1,f.Server.SubmissionWrites);
        var link=f.Desktop.SupplementalReviewLink(received.Id,request.Event.Id,f.Store);var supplement=f.Store.SaveSubmissionDraft(new(1,Guid.NewGuid(),0,result.FlightId,[result.Id],null,"Explicit additional original observations",f.Upload,link),f.Science);Assert.Null(supplement.Consent);Assert.Null(f.Store.NextApprovedSubmission());await f.ReviewApprove(supplement);var extra=await delivery.Send(supplement.Id,default);Assert.Equal(SubmissionDeliveryState.ServerReceived,extra.State);Assert.NotEqual(received.Id,extra.Id);
        var updated=await ReviewGet<ResearchReviewSnapshot>(f.Server,ReviewPath(root));Assert.Equal(ResearchReviewState.UpdatedSubmission,updated.Summary.State);Assert.Equal(2,updated.Summary.PackageCount);Assert.Equal(originalHash,f.Store.SubmissionDraft(received.Id).Consent!.PayloadSha256);var selected=(await f.Server.Post(ReviewPath(root)+"/evidence",new ResearchReviewSelection(target.CardId,target.RequirementKey,[root,extra.Receipt!.Id]))).Deserialize<ResearchReviewEvidencePage>(WireJson.Options)!;Assert.True(selected.Assessment.CanApprove,string.Join(";",selected.Assessment.Blockers));Assert.Contains(selected.Items,i=>i.ReceiptId==extra.Receipt.Id&&i.Item.Data.Observations?.Any(o=>o.Value==17.1234567)==true);
        using(var unresolved=await ReviewSend(f.Server,ReviewPath(root)+"/commands",new ResearchReviewCommand(1,Guid.NewGuid(),updated.Summary.Revision,ResearchReviewAction.Approve,target,"",[new(extra.Receipt.Id,"*")],ConfirmApproval:true)))Assert.Equal(HttpStatusCode.Conflict,unresolved.StatusCode);
        var approved=await ReviewCommand(f,received,ResearchReviewAction.Approve,"The independently received original observations fulfill the published collection bands; resolved the requested missing readings.",target,[new(extra.Receipt.Id,"*")],[request.Event.Id]);Assert.Equal(ResearchReviewState.Approved,approved.Review.Summary.State);var history=await f.Desktop.ReviewHistory(received.Id,check,0,f.Store,default);Assert.Contains(history.Items,e=>e.Action==ResearchReviewAction.PilotResponse);Assert.Contains(history.Items,e=>e.Action==ResearchReviewAction.SupplementalReceived);Assert.Equal(approved.Event.Sha256,history.HeadSha256);
        await f.Restart();status=await f.Desktop.ReviewStatus(received.Id,check,f.Store,default);Assert.True(status.VerifiedNow);Assert.Equal(ResearchReviewState.Approved,status.Retained!.Snapshot.Summary.State);using(var scope=f.Server.App.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<OrganizationDatabase>();Assert.Equal(originalHash,(await db.Submissions.SingleAsync(s=>s.ReceiptId==root)).PayloadSha256);var immutable=await db.ReviewEvents.FirstAsync();immutable.PayloadJson="changed";await Assert.ThrowsAsync<InvalidOperationException>(()=>db.SaveChangesAsync());}
        await f.Server.DisposeAsync();status=await f.Desktop.ReviewStatus(received.Id,check,f.Store,default);Assert.False(status.VerifiedNow);Assert.Equal(ResearchReviewState.Approved,status.Retained!.Snapshot.Summary.State);Assert.Contains("previously checked",status.Message);f.Server=await Start(f.Database,f.Root,"Evidence Research Lab",existing:true,retainedOrigin:f.Server.Origin);
    }
    [PostgresFact]public async Task ReviewDecisionRetriesAreIdempotentConcurrentFindingsConflictAndGeneralCommentHasExplicitPilotReply()
    {
        await using var f=await SubmissionFixture.Create();var c=await f.Card(ObservationResearch.Template);var result=await f.Record(c.Prepared,3,notes:true);var row=f.Draft(result);await f.ReviewApprove(row);using var delivery=f.Delivery();row=await delivery.Send(row.Id,default);var root=row.Receipt!.Id;var s=await ReviewGet<ResearchReviewSnapshot>(f.Server,ReviewPath(root));var target=new ReviewTarget(c.Prepared.Card.Id,"documentation");var command=new ResearchReviewCommand(1,Guid.NewGuid(),s.Summary.Revision,ResearchReviewAction.Comment,Note:"Please explain your observation method.");var a=await f.Server.Post(ReviewPath(root)+"/commands",command);var b=await f.Server.Post(ReviewPath(root)+"/commands",command);Assert.Equal(a.GetRawText(),b.GetRawText());var comment=a.Deserialize<ResearchReviewCommandResult>(WireJson.Options)!;
        var reply=await f.Desktop.RespondToReview(row.Id,new(f.Upload,root,new(1,Guid.NewGuid(),comment.Review.Summary.Revision,ResearchReviewAction.PilotResponse,Note:"These are my written observations, not sensor measurements.",RespondTo:comment.Event.Id,ExplicitSharing:true)),f.Store,default);Assert.Equal(comment.Event.Id,reply.Event.RespondTo);
        var revision=reply.Review.Summary.Revision;var decision=new ResearchReviewCommand(1,Guid.NewGuid(),revision,ResearchReviewAction.Reject,target,"The present documentation is not adequate.");var concurrent=await Task.WhenAll(ReviewSend(f.Server,ReviewPath(root)+"/commands",decision),ReviewSend(f.Server,ReviewPath(root)+"/commands",decision with{RequestId=Guid.NewGuid(),Note="Another finding"}));Assert.Single(concurrent,r=>r.StatusCode==HttpStatusCode.OK);Assert.Single(concurrent,r=>r.StatusCode==HttpStatusCode.Conflict);foreach(var r in concurrent)r.Dispose();
        var accepted=await ReviewCommand(f,row,ResearchReviewAction.Approve,"On further review the original documentation meets the exact stated documentation goal, without proving the pilot's interpretation.",target,[new(root,"*")]);Assert.Equal(ResearchReviewState.Approved,accepted.Review.Summary.State);var history=await ReviewGet<ResearchReviewHistory>(f.Server,ReviewPath(root)+"/history");Assert.Single(history.Items,e=>e.Action==ResearchReviewAction.Reject);Assert.Single(history.Items,e=>e.Action==ResearchReviewAction.Approve);Assert.Equal(ResearchAttemptOutcome.CollectionComplete,f.Store.ResearchAttempt(result.Id).Outcome);using var missingReason=await ReviewSend(f.Server,ReviewPath(root)+"/commands",new ResearchReviewCommand(1,Guid.NewGuid(),accepted.Review.Summary.Revision,ResearchReviewAction.Reject,target));Assert.Equal(HttpStatusCode.BadRequest,missingReason.StatusCode);
    }
    [PostgresFact]public async Task ReviewQueueAndImmutableConversationUsePagedAuthoritativeInventoryAndBackfillExistingReceipts()
    {
        await using var f=await SubmissionFixture.Create();var c=await f.Card(incomplete:true);var result=await f.Record(c.Prepared);var row=f.Draft(result);await f.ReviewApprove(row);var approved=f.Store.SubmissionDraft(row.Id);var doc=f.Store.ApprovedSubmissionDocument(row.Id,f.Science);SubmissionReceipt? receipt=null;
        // Page-scale fixture: one actual delivery plus 20 independently hashed retained P17 records,
        // inserted through the existing metadata service. Do not weaken the real six/minute receipt limit.
        using(var packet=await f.Packet(doc,approved.Consent)){Assert.Equal(HttpStatusCode.OK,packet.StatusCode);receipt=await packet.Content.ReadFromJsonAsync<SubmissionReceipt>(WireJson.Options);}
        for(int i=0;i<20;i++){using var scope=f.Server.App.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<OrganizationDatabase>();var packet=doc with{Manifest=doc.Manifest with{Id=Guid.NewGuid(),Name="Paged receipt "+i}};var bytes=SubmissionEvidenceProtocol.Bytes(packet);var received=new SubmissionReceipt(1,Guid.NewGuid(),packet.Manifest.Id,packet.Manifest.OrganizationId,packet.Manifest.PilotId,packet.Manifest.CampaignId,PreflightReadiness.Hash(packet.Manifest),PreflightReadiness.Hash(packet),bytes,DateTimeOffset.UtcNow,"Received / Awaiting Review",SubmissionEvidenceProtocol.RetentionDisclosure);await using var tx=await db.Database.BeginTransactionAsync();db.Submissions.Add(new(){Id=packet.Manifest.Id,PilotId=packet.Manifest.PilotId,ReceiptId=received.Id,CampaignId=packet.Manifest.CampaignId,Name=packet.Manifest.Name,SearchName=packet.Manifest.Name.ToUpperInvariant(),ManifestSha256=received.ManifestSha256,PayloadSha256=received.PayloadSha256,PayloadBytes=bytes,PayloadJson=JsonSerializer.Serialize(packet,WireJson.Options),ReceiptJson=JsonSerializer.Serialize(received,WireJson.Options),ReceivedUtc=received.ReceivedUtc});await scope.ServiceProvider.GetRequiredService<OrganizationReviews>().Received(packet,received,default);await db.SaveChangesAsync();await tx.CommitAsync();}

        var page=await ReviewGet<OrganizationPage<ResearchReviewSummary>>(f.Server,"/api/organization/reviews");Assert.Equal(20,page.Items.Length);Assert.Equal(20,page.NextOffset);Assert.Single((await ReviewGet<OrganizationPage<ResearchReviewSummary>>(f.Server,"/api/organization/reviews?offset=20")).Items);Assert.Empty((await ReviewGet<OrganizationPage<ResearchReviewSummary>>(f.Server,"/api/organization/reviews?search=Missing")).Items);var root=receipt!.Id;
        for(int i=0;i<21;i++){var snap=await ReviewGet<ResearchReviewSnapshot>(f.Server,ReviewPath(root));await f.Server.Post(ReviewPath(root)+"/commands",new ResearchReviewCommand(1,Guid.NewGuid(),snap.Summary.Revision,ResearchReviewAction.Comment,Note:"Paged review note "+i));}var history=await ReviewGet<ResearchReviewHistory>(f.Server,ReviewPath(root)+"/history");Assert.Equal(20,history.Items.Length);Assert.Equal(20,history.NextAfter);var next=await ReviewGet<ResearchReviewHistory>(f.Server,ReviewPath(root)+"/history?after=20");Assert.Equal(2,next.Items.Length);Assert.Equal(history.Items.Last().Sha256,next.Items[0].PreviousSha256);
        // Reproduce an actual pre-P18 receipt by removing only new review metadata using fixture SQL, not production APIs.
        using(var scope=f.Server.App.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<OrganizationDatabase>();await db.Database.ExecuteSqlInterpolatedAsync($"DELETE FROM organization.\"ReviewEvents\" WHERE \"RootId\"={root}");await db.Database.ExecuteSqlInterpolatedAsync($"DELETE FROM organization.\"ReviewPackages\" WHERE \"RootId\"={root}");await db.Database.ExecuteSqlInterpolatedAsync($"DELETE FROM organization.\"ReviewRequirements\" WHERE \"RootId\"={root}");await db.Database.ExecuteSqlInterpolatedAsync($"DELETE FROM organization.\"Reviews\" WHERE \"Id\"={root}");}await f.Restart();var restored=await ReviewGet<ResearchReviewSnapshot>(f.Server,ReviewPath(root));Assert.Equal(1,restored.Summary.Revision);Assert.Equal(receipt.ReceivedUtc,restored.Summary.ReceivedUtc);Assert.Equal(receipt.PayloadSha256,restored.Summary.RootPayloadSha256);Assert.Equal(21,await f.Received());
    }
    [PostgresFact]public async Task ReviewerNeedsExplicitCampaignAccessCannotManageAndRevocationBlocksEveryEvidenceEndpoint()
    {
        await using var f=await SubmissionFixture.Create();var c=await f.Card(incomplete:true);var result=await f.Record(c.Prepared);await f.ReviewApprove(f.Draft(result));using var delivery=f.Delivery();var row=await delivery.Send(f.Store.NextApprovedSubmission()!.Id,default);var root=row.Receipt!.Id;
        var invite=(await f.Server.Post("/api/organization/members/invitations",new OrganizationInvitationRequest(1,Guid.NewGuid()))).Deserialize<OrganizationInvitationView>(WireJson.Options)!;using var reviewer=new HttpClient(new HttpClientHandler{UseCookies=true}){BaseAddress=new(f.Server.Origin)};var identity=await ReviewGet<OrganizationPublicIdentity>(f.Server,"/api/public/organization");using(var enrolled=await ReviewSend(f.Server,"/api/enrollment",new OrganizationJoinRequest(1,identity.Id,"reviewer","ResearchOnly!2026Flight",new Uri(invite.Link!).Fragment[6..],"Review evidence",true),reviewer))Assert.Equal(HttpStatusCode.OK,enrolled.StatusCode);using(var login=await ReviewSend(f.Server,"/api/sign-in",new OrganizationLoginRequest("reviewer","ResearchOnly!2026Flight"),reviewer))Assert.Equal(HttpStatusCode.OK,login.StatusCode);
        var members=await ReviewGet<OrganizationPage<OrganizationMemberView>>(f.Server,"/api/organization/members");var member=members.Items.Single(m=>m.Name=="reviewer");using(var denied=await reviewer.GetAsync("/api/organization/reviews"))Assert.Equal(HttpStatusCode.Forbidden,denied.StatusCode);await f.Server.Post("/api/organization/members/"+member.UserId,new OrganizationMemberRequest(1,Guid.NewGuid(),member.Revision,OrganizationRoles.Reviewer,OrganizationMembershipState.Active),HttpMethod.Put);using(var login=await ReviewSend(f.Server,"/api/sign-in",new OrganizationLoginRequest("reviewer","ResearchOnly!2026Flight"),reviewer))Assert.Equal(HttpStatusCode.OK,login.StatusCode);
        var empty=await reviewer.GetFromJsonAsync<OrganizationPage<ResearchReviewSummary>>("/api/organization/reviews",WireJson.Options);Assert.Empty(empty!.Items);using(var denied=await reviewer.GetAsync(ReviewPath(root)))Assert.Equal(HttpStatusCode.Forbidden,denied.StatusCode);await f.Server.Post("/api/organization/reviews/permissions/"+c.Published.CampaignId,new CampaignReviewPermission(1,Guid.NewGuid(),0,member.UserId,true));Assert.Single((await reviewer.GetFromJsonAsync<OrganizationPage<ResearchReviewSummary>>("/api/organization/reviews",WireJson.Options))!.Items);using(var allowed=await reviewer.GetAsync(ReviewPath(root)))Assert.Equal(HttpStatusCode.OK,allowed.StatusCode);
        using(var ownOnly=await reviewer.GetAsync("/api/membership/reviews/"+root))Assert.Equal(HttpStatusCode.NotFound,ownOnly.StatusCode);
        var original=await ReviewGet<ResearchReviewSnapshot>(f.Server,ReviewPath(root));var managerCommand=new ResearchReviewCommand(1,Guid.NewGuid(),original.Summary.Revision,ResearchReviewAction.Comment,Note:"Manager concurrent note");var reviewerCommand=managerCommand with{RequestId=Guid.NewGuid(),Note="Separate Reviewer concurrent note"};var race=await Task.WhenAll(ReviewSend(f.Server,ReviewPath(root)+"/commands",managerCommand),ReviewSend(f.Server,ReviewPath(root)+"/commands",reviewerCommand,reviewer));Assert.Single(race,r=>r.StatusCode==HttpStatusCode.OK);Assert.Single(race,r=>r.StatusCode==HttpStatusCode.Conflict);foreach(var r in race)r.Dispose();
        using(var denied=await reviewer.GetAsync("/api/organization/members"))Assert.Equal(HttpStatusCode.Forbidden,denied.StatusCode);using(var denied=await reviewer.GetAsync("/api/organization/submissions"))Assert.Equal(HttpStatusCode.Forbidden,denied.StatusCode);
        await f.Server.Post("/api/organization/reviews/permissions/"+c.Published.CampaignId,new CampaignReviewPermission(1,Guid.NewGuid(),1,member.UserId,false));foreach(var suffix in new[]{"","/packages","/history","/item?receipt="+root+"&key=no"}){using var denied=await reviewer.GetAsync(ReviewPath(root)+suffix);Assert.Equal(HttpStatusCode.Forbidden,denied.StatusCode);}using(var denied=await ReviewSend(f.Server,ReviewPath(root)+"/evidence",new ResearchReviewSelection(c.Prepared.Card.Id,"conditions",[root]),reviewer))Assert.Equal(HttpStatusCode.Forbidden,denied.StatusCode);
        using var native=new HttpClient{BaseAddress=new(f.Server.Origin)};native.DefaultRequestHeaders.Authorization=new("Bearer",f.Vault.Read(f.Read));Assert.Equal(HttpStatusCode.Forbidden,(await native.GetAsync("/api/member/reviews/"+root)).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await f.Server.Browser.GetAsync(ReviewPath(Guid.NewGuid()))).StatusCode);
        var active=(await ReviewGet<OrganizationPage<OrganizationMemberView>>(f.Server,"/api/organization/members")).Items.Single(m=>m.UserId==member.UserId);await f.Server.Post("/api/organization/members/"+member.UserId,new OrganizationMemberRequest(1,Guid.NewGuid(),active.Revision,OrganizationRoles.Reviewer,OrganizationMembershipState.Suspended),HttpMethod.Put);using var revoked=await reviewer.GetAsync("/api/organization/reviews");Assert.Equal(HttpStatusCode.Unauthorized,revoked.StatusCode);

    }
