        ResearchCardResult Control(ResearchCardAction action,int point=0){var s=coordinator.PersonalResearch(flight.Id);return coordinator.ControlPersonalResearch(new(1,flight.Id,Guid.NewGuid(),s.Revision,action,c.Prepared.Card.Id,s.Cards.Single().OpenAttempt?.Id,action==ResearchCardAction.BeginAttempt?c.Prepared.Card.Procedure!.Points[point].Id:null));}
