    {
        await using var f=await SubmissionFixture.Create();var c=await f.Card(incomplete:true);var result=await f.Record(c.Prepared);await f.ReviewApprove(f.Draft(result));using var delivery=f.Delivery();var row=await delivery.Send(f.Store.NextApprovedSubmission()!.Id,default);var root=row.Receipt!.Id;var request=await ReviewCommand(f,row,ResearchReviewAction.RequestEvidence,"Please explain the interrupted short interval.",new(c.Prepared.Card.Id,"conditions"));var command=new ResearchReviewCommand(1,Guid.NewGuid(),request.Review.Summary.Revision,ResearchReviewAction.PilotResponse,new(c.Prepared.Card.Id,"conditions"),"My explicitly approved reply.",RespondTo:request.Event.Id,ExplicitSharing:true);
        using var native=new HttpClient{BaseAddress=new(f.Server.Origin)};native.DefaultRequestHeaders.Authorization=new("Bearer",f.Vault.Read(f.Upload));var connection=new Npgsql.NpgsqlConnectionStringBuilder(System.Environment.GetEnvironmentVariable("AEROSCIENCE_ORG_TEST_DATABASE")){Database=f.Database};await using var holder=new Npgsql.NpgsqlConnection(connection.ConnectionString);await holder.OpenAsync();await using var tx=await holder.BeginTransactionAsync();await using(var take=new Npgsql.NpgsqlCommand("SELECT pg_advisory_xact_lock(7014001)",holder,tx))await take.ExecuteNonQueryAsync();var send=native.PostAsJsonAsync($"/api/member/reviews/{root}/respond",command,WireJson.Options);var deadline=DateTime.UtcNow.AddSeconds(10);var waiting=false;await using var observer=new Npgsql.NpgsqlConnection(connection.ConnectionString);await observer.OpenAsync();while(DateTime.UtcNow<deadline){await using var check=new Npgsql.NpgsqlCommand("SELECT EXISTS (SELECT 1 FROM pg_stat_activity WHERE datname=current_database() AND wait_event='advisory' AND query LIKE '%pg_advisory_xact_lock%')",observer);waiting=(bool)(await check.ExecuteScalarAsync())!;if(waiting)break;await Task.Delay(20);}Assert.True(waiting,"The real pilot response must reach the authoritative membership transaction lock.");using(var scope=f.Server.App.Services.CreateScope())await scope.ServiceProvider.GetRequiredService<OrganizationDatabase>().DeviceGrants.Where(g=>g.Id==f.Upload).ExecuteUpdateAsync(s=>s.SetProperty(g=>g.Revoked,true));await tx.CommitAsync();using var denied=await send;Assert.Equal(HttpStatusCode.Unauthorized,denied.StatusCode);using var history=await native.GetAsync($"/api/member/reviews/{root}/history");Assert.Equal(HttpStatusCode.Unauthorized,history.StatusCode);var actual=await ReviewGet<ResearchReviewHistory>(f.Server,ReviewPath(root)+"/history");Assert.DoesNotContain(actual.Items,e=>e.Action==ResearchReviewAction.PilotResponse);Assert.Equal(2,actual.Items.Length);Assert.Equal(1,await f.Received());
    }
